CREATE TABLE "MarketplaceListing" ("id" TEXT NOT NULL,"contentItemId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"price" DECIMAL(65,30) NOT NULL DEFAULT 0,"previousPrice" DECIMAL(65,30),"currency" TEXT NOT NULL DEFAULT 'INR',"license" TEXT NOT NULL DEFAULT 'INSTITUTION_PERSONAL',"purchaseEnabled" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "MarketplaceListing_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "MarketplaceListing_contentItemId_key" ON "MarketplaceListing"("contentItemId");CREATE INDEX "MarketplaceListing_status_price_updatedAt_idx" ON "MarketplaceListing"("status","price","updatedAt");
