CREATE TABLE "MarketplaceWishlistCollection" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"name" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "MarketplaceWishlistCollection_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "MarketplaceWishlistCollection_userId_name_key" ON "MarketplaceWishlistCollection"("userId","name");CREATE TABLE "MarketplaceWishlistItem" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"collectionId" TEXT NOT NULL,"listingId" TEXT NOT NULL,"contentItemId" TEXT NOT NULL,"availabilityAlert" BOOLEAN NOT NULL DEFAULT false,"priceAlert" BOOLEAN NOT NULL DEFAULT false,"priceAtSave" DECIMAL(65,30),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "MarketplaceWishlistItem_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "MarketplaceWishlistItem_userId_listingId_key" ON "MarketplaceWishlistItem"("userId","listingId");CREATE INDEX "MarketplaceWishlistItem_collectionId_createdAt_idx" ON "MarketplaceWishlistItem"("collectionId","createdAt");
